UPDATE lessons SET title='Year 3, Week 18, Lesson 2: Finding unknown numbers', data=json_patch(data,'{"child_mission":"Unknown numbers can be shown with a box or letter. Solve by using inverse operations or related facts while keeping equality.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nFind n and check: (a) n−23=41 (b) 9×n=72.\n\nFEEDBACK\n(a) n=64 check 64−23=41 (b) n=8 check 9×8=72.\n\nWATCH FOR\nLeaving the check out allows arithmetic slips to pass unnoticed.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nSolve twelve unknown-number problems. Substitute to check each. Write two word stories that match two of your equations.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Unknown numbers can be shown with a box or letter. Solve by using inverse operations or related facts while keeping equality.","lesson_number":2,"lesson_role":"Strategies","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-AR-01"],"parent_notes":"Parent: Marking guidance for the independent task: Solve twelve unknown-number problems. Substitute to check each. Write two word stories that match two of your equations. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for unknown; key places/values named. Do not award marks for retyping the model.\n\nParent: Written model 2: Sample misconception: Leaving the check out allows arithmetic slips to pass unnoticed.. Correction uses (a) n=64 check 64−23=41 (b) n=8 check 9×8=72.. Why: restores accurate unknown.\n\nParent: Likely misconception: Leaving the check out allows arithmetic slips to pass unnoticed. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses unknown with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with unknown, show corrected working, and say why the correction works.\n\nParent: Marking notes: Accept any mathematically valid solution that uses new numbers, shows working for unknown, and names places/values. Reject copied model numbers. / Accept a named misconception about unknown, corrected working, and a method reason. Reject vague “I was wrong” with no repair..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for unknown. The other choices miss a key step or use a common mistake.","options":["(a) n=64 check 64−23=41 (b) n=8 check 9×8=72","Leaving the check out allows arithmetic slips to pass unnoticed","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Find n and check: (a) n−23=41 (b) 9×n=72. Which response is most accurate?","type":"multiple_choice"},{"correct_index":1,"explanation":"This is the misconception to avoid for unknown; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Careful use of inverse and explain why it matters with clear evidence","Leaving the check out allows arithmetic slips to pass unnoticed","Unknown numbers can be shown with a box or letter","(a) n=64 check 64−23=41 (b) n=8 check 9×8=72"],"question":"Which statement is a common mistake when working with unknown?","type":"multiple_choice"},{"correct_index":0,"explanation":"Understanding is shown by new evidence and a named inverse and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Apply unknown to new material and name the inverse and explain why it matters used","Repeat the worked example wording with no new evidence","Leaving the check out allows arithmetic slips to pass unnoticed","Name inverse and explain why it matters only, without linking it to unknown"],"question":"Which response best applies unknown with new evidence?","type":"multiple_choice"},{"correct_index":3,"explanation":"Mathematics answers need labelled working tied to place value, quantity or the asked operation. The other choices miss a key step or use a common mistake.","options":["Write only a final number with no working","Change digits to look neater without checking place value","Leaving the check out allows arithmetic slips to pass unnoticed","Show each place, value or step and say why that step is valid"],"question":"Which working best supports a correct answer for this lesson on unknown?","type":"multiple_choice"},{"correct_index":2,"explanation":"The correct statement applies the taught unknown method; the others break place value, units or the asked quantity. The other choices miss a key step or use a common mistake.","options":["Read 23 from left to right as ones only, ignoring place value","Ignore units and treat 23 and 41 as interchangeable","(a) n=64 check 64−23=41 (b) n=8 check 9×8=72","Leaving the check out allows arithmetic slips to pass unnoticed"],"question":"Using the method for unknown, which statement is true?","type":"multiple_choice"},{"correct_index":2,"explanation":"Disagreement is resolved by checking places, operations and the question focus, not by blending answers. The other choices miss a key step or use a common mistake.","options":["Delete units so the answers appear to match","Average the two answers without checking either","Recheck places, operations and whether the question asked for the quantity you computed","Pick the longer-looking working automatically"],"question":"If two methods disagree on a unknown problem with numbers such as 23 and 41, what should you check first?","type":"multiple_choice"},{"correct_index":3,"explanation":"Transfer requires new numbers with the same mathematical method and a named reason. The other choices miss a key step or use a common mistake.","options":["Retype the worked model numbers 23 and 41 as the answer","Change only handwriting and keep the same numbers","Leaving the check out allows arithmetic slips to pass unnoticed","Use the same unknown method on new numbers and name the places or values that matter"],"question":"Solve a fresh unknown problem that uses different numbers from the worked model and explain one key step.?","type":"multiple_choice"},{"correct_index":2,"explanation":"Recognising the warned misconception protects accuracy on new problems. The other choices miss a key step or use a common mistake.","options":["(a) n=64 check 64−23=41 (b) n=8 check 9×8=72","Label units when comparing 23 with 41","Leaving the check out allows arithmetic slips to pass unnoticed","Unknown numbers can be shown with a box or letter"],"question":"Which error is the lesson warning against for unknown?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept any mathematically valid solution that uses new numbers, shows working for unknown, and names places/values. Reject copied model numbers.","question":"Solve one fresh problem that uses unknown with different numbers from the worked model. Show working and name the places or values that matter.","sample_answer":"Sample: new numbers solved with visible working for unknown; key places/values named. Do not award marks for retyping the model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a named misconception about unknown, corrected working, and a method reason. Reject vague “I was wrong” with no repair.","question":"Describe one likely mistake with unknown, show corrected working, and say why the correction works.","sample_answer":"Sample misconception: Leaving the check out allows arithmetic slips to pass unnoticed.. Correction uses (a) n=64 check 64−23=41 (b) n=8 check 9×8=72.. Why: restores accurate unknown.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent working and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-mat-y3-w18-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA mathematics alignment using verified outcome code wording where recorded in lesson-pipeline/sources; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise unknown.","Read the mission before you start calculating.","Keep the place or unit you are working with in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your working with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the place or distance that carries the method.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore place value or working.","Prefer accurate method over a guess that merely looks neat."],"submit":["Confirm that your working and reason are both present.","Proofread digits, places and operation signs.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact place, value or distance before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key numbers.","Say what each number represents in the method.","A final answer alone is weaker than labelled working."],"teach2":["Compare a weak attempt with stronger working.","Change the value or method, not only how neat it looks.","Name the mistake you are repairing."],"teach3":["Choose fresh numbers that still use the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original working and a short reason.","Save work that shows the skill on new numbers."]},"subject":"Number and Algebra","success_criteria":["I can use unknown with a specific example from this lesson.","I can identify inverse and explain why it matters.","I can practise represent independently on a new prompt.","I can notice solve needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"Unknown numbers can be shown with a box or letter.","options":["An answer copied without understanding","Unknown numbers can be shown with a box or letter","A guess with no working","A calculation unrelated to the numbers given"],"question":"Which choice best applies this lesson idea about unknown with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nn+17=45 → n=28. Or 8×n=56 → n=7. Check by substituting back.\n\nTRY FIRST\nFind n and check: (a) n−23=41 (b) 9×n=72.\n\nFEEDBACK\n(a) n=64 check 64−23=41 (b) n=8 check 9×8=72.","explain":"Unknown numbers can be shown with a box or letter. Solve by using inverse operations or related facts while keeping equality.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Leaving the check out allows arithmetic slips to pass unnoticed. Correct the value or method, not just the appearance of the digits.","title":"Understand and model","visual":[{"alt":"Letter unknown solved with an inverse.","caption":"Substitute back to confirm.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Unknown</text><text x=\"28\" y=\"78\">n+17=45</text><text x=\"358\" y=\"42\">n</text><text x=\"358\" y=\"78\">28</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which number or place matters most.","who":"pip"},{"text":"Name the places, values or distances that carry the method before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: n+17=45 → n=28. Or 8×n=56 → n=7. Check by substituting back. Then write your own working.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which number or place matters most.\nJuno: Name the places, values or distances that carry the method before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: n+17=45 → n=28. Or 8×n=56 → n=7. Check by substituting back. Then write your own working."}}]},{"check":{"correct_index":1,"explanation":"Make the method visible: name the values, places or steps you used and say why that step is valid.","options":["An answer copied without understanding","Make the method visible: name the values, places or steps you used and say why that step is valid","A guess with no working","A calculation unrelated to the numbers given"],"question":"Which choice best applies this lesson idea about unknown with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nn+17=45 → n=28. Or 8×n=56 → n=7. Check by substituting back. Look at each number, place or distance that carries the method.\n\nTRY FIRST\nWrite the key numbers from the model and say what each one represents in the method.\n\nFEEDBACK\nThe most useful working names the quantities and the reason for each step, not only the final answer.","explain":"Make the method visible: name the values, places or steps you used and say why that step is valid.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only the final answer without working does not show the method. Correct the value or method, not just the appearance of the digits.","title":"Show the working","visual":[{"alt":"Checked solution ready for a word story.","caption":"The check catches arithmetic slips.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Check</text><text x=\"28\" y=\"78\">9×n=72 → n=8</text><text x=\"358\" y=\"42\">Story</text><text x=\"358\" y=\"78\">match the equation</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally incorrect attempt as a comparison.","options":["A guess with no working","A calculation unrelated to the numbers given","Use an intentionally incorrect attempt as a comparison","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about unknown with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nLeaving the check out allows arithmetic slips to pass unnoticed. Here is a more productive model: n+17=45 → n=28. Or 8×n=56 → n=7. Check by substituting back.\n\nTRY FIRST\nDescribe why the warned-against approach gives the wrong value or meaning, then write corrected working.\n\nFEEDBACK\n(a) n=64 check 64−23=41 (b) n=8 check 9×8=72.","explain":"Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the answer without repairing the method does not fix the error. Leaving the check out allows arithmetic slips to pass unnoticed. Correct the value or method, not just the appearance of the digits.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the method on new numbers or a new context, not a copy of the worked example.","options":["A calculation unrelated to the numbers given","An answer copied without understanding","A guess with no working","Use the method on new numbers or a new context, not a copy of the worked example"],"question":"Which choice best applies this lesson idea about unknown with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nUnknown numbers can be shown with a box or letter. Solve by using inverse operations or related facts while keeping equality. Now choose different numbers to show you can transfer the method.\n\nTRY FIRST\nSolve one fresh problem that uses the same skill and write a short reason for your answer.\n\nFEEDBACK\nThe new problem should use the same method as the model, but contain different numbers.","explain":"Use the method on new numbers or a new context, not a copy of the worked example. Review accuracy and units or places.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new numbers. Correct the value or method, not just the appearance of the digits.","title":"Transfer to a new problem"}],"title":"Year 3, Week 18, Lesson 2: Finding unknown numbers","unit_number":5,"unit_title":"Patterns, number sentences and money","week":18,"week_in_unit":2,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nn+17=45 → n=28. Or 8×n=56 → n=7. Check by substituting back.\n\nWrite what makes this example accurate, naming the places, values or distances used.","worked_visuals":[{"alt":"Letter unknown solved with an inverse.","caption":"Substitute back to confirm.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Unknown</text><text x=\"28\" y=\"78\">n+17=45</text><text x=\"358\" y=\"42\">n</text><text x=\"358\" y=\"78\">28</text></g></svg>"},{"alt":"Checked solution ready for a word story.","caption":"The check catches arithmetic slips.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Check</text><text x=\"28\" y=\"78\">9×n=72 → n=8</text><text x=\"358\" y=\"42\">Story</text><text x=\"358\" y=\"78\">match the equation</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-mat-y3-w18-l2' AND family_id IS NULL;
